using System.IO;using UnityEngine;using UnityEditor;
namespace LWS.TruckFieldGoal.Editor {
public static class FieldGoalPreviewAuthoring {
 public static void Create(FieldGoalMatch m){Directory.CreateDirectory("Assets/TruckFieldGoal/Art");var roots=new[]{m.truck.transform,m.football.transform,m.boot.transform};var positions=new Vector3[3];var rotations=new Quaternion[3];for(int i=0;i<3;i++){positions[i]=roots[i].position;rotations[i]=roots[i].rotation;}m.truck.transform.SetPositionAndRotation(new Vector3(0,.7f,-4),Quaternion.Euler(0,-8,0));m.truck.ApplyColor(m.setup.players[0].color);m.football.transform.SetPositionAndRotation(new Vector3(1,.9f,0),Quaternion.Euler(10,35,25));m.boot.transform.rotation=Quaternion.Euler(15,0,0);var camera=m.cameraRig.view;var p=camera.transform.position;var q=camera.transform.rotation;var old=camera.targetTexture;var active=RenderTexture.active;var rt=new RenderTexture(768,432,24);rt.Create();camera.targetTexture=rt;camera.transform.SetPositionAndRotation(new Vector3(-14,10,-18),Quaternion.LookRotation(new Vector3(0,3,7)-new Vector3(-14,10,-18)));camera.Render();RenderTexture.active=rt;var image=new Texture2D(768,432,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,768,432),0,0);image.Apply();string path="Assets/TruckFieldGoal/Art/Menu Preview.png";File.WriteAllBytes(path,image.EncodeToPNG());Object.DestroyImmediate(image);camera.targetTexture=old;RenderTexture.active=active;rt.Release();Object.DestroyImmediate(rt);camera.transform.SetPositionAndRotation(p,q);for(int i=0;i<3;i++)roots[i].SetPositionAndRotation(positions[i],rotations[i]);AssetDatabase.ImportAsset(path);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.textureType=TextureImporterType.Sprite;importer.spriteImportMode=SpriteImportMode.Single;importer.mipmapEnabled=false;importer.SaveAndReimport();}
}
}
